INSERT INTO red_flag_entries (phrase, category, explanation, what_to_do, created_at, updated_at) VALUES
('send GCash', 'Financial', 'Legitimate employers never ask you to send money via GCash before or during hiring. This is a classic upfront payment scam.', 'Do not send any money. Report the job post immediately.', NOW(), NOW()),
('processing fee', 'Financial', 'Real companies do not charge applicants a processing fee. This is used to extract money from desperate job seekers.', 'Refuse to pay and report the listing.', NOW(), NOW()),
('registration fee', 'Financial', 'No legitimate employer requires a registration fee to apply or get hired.', 'Walk away and report the post.', NOW(), NOW()),
('security deposit', 'Financial', 'Asking for a security deposit before employment is a scam tactic to steal money from applicants.', 'Do not pay anything. Report the recruiter.', NOW(), NOW()),
('refundable insurance', 'Financial', 'Scammers often promise refunds that never come. Any upfront payment request is a red flag.', 'Refuse the payment and report the listing.', NOW(), NOW()),
('account activation fee', 'Financial', 'There is no such thing as an account activation fee for a legitimate job. This is a scam.', 'Do not pay. Report immediately.', NOW(), NOW()),
('pay for training', 'Financial', 'Legitimate employers pay you during training, not the other way around.', 'Refuse and report the job post.', NOW(), NOW()),
('pay training materials', 'Financial', 'Real companies provide training materials at no cost to the applicant.', 'Do not pay. Look for legitimate opportunities.', NOW(), NOW()),
('buy equipment', 'Financial', 'Scammers ask you to buy equipment with promises of reimbursement that never arrives.', 'Do not purchase anything. Report the post.', NOW(), NOW()),
('reimburse through check', 'Financial', 'Fake check scams ask you to deposit a check and send back part of the funds. The check will bounce.', 'Never deposit checks from unknown employers.', NOW(), NOW()),
('purchase software', 'Financial', 'Legitimate employers provide necessary software. Being asked to buy it is a scam tactic.', 'Refuse and report the listing.', NOW(), NOW()),
('move to Telegram', 'Contact Method', 'Moving communication to Telegram removes accountability and is a common scammer tactic to avoid being traced.', 'Do not continue the conversation on external apps.', NOW(), NOW()),
('contact via WhatsApp only', 'Contact Method', 'Legitimate recruiters use official company emails or platforms, not personal messaging apps only.', 'Be cautious. Verify the company through official channels.', NOW(), NOW()),
('message on Viber', 'Contact Method', 'Requesting communication only through Viber bypasses official hiring platforms and is suspicious.', 'Verify the employer through official channels before proceeding.', NOW(), NOW()),
('add me on Signal', 'Contact Method', 'Signal is an encrypted app scammers use to avoid detection. Legitimate recruiters don''t exclusively use it.', 'Do not add unknown recruiters on personal messaging apps.', NOW(), NOW()),
('join this Telegram group', 'Contact Method', 'Scammers use Telegram groups to coordinate fraud and pressure multiple victims at once.', 'Do not join unknown Telegram groups for job offers.', NOW(), NOW()),
('interview on Skype', 'Contact Method', 'While Skype can be legitimate, scammers prefer it to avoid leaving an official trail. Verify the company first.', 'Research the company thoroughly before any online interview.', NOW(), NOW()),
('personal email address', 'Contact Method', 'Legitimate company recruiters use official company email domains, not personal Gmail or Yahoo accounts.', 'Verify the recruiter''s email matches the company domain.', NOW(), NOW()),
('no experience needed', 'Unrealistic Offer', 'Jobs requiring no experience but offering high pay are often scams designed to attract desperate applicants.', 'Research the company and verify the job is legitimate before applying.', NOW(), NOW()),
('earn up to 50000', 'Unrealistic Offer', 'Unusually high salary claims with vague job descriptions are a hallmark of scam job postings.', 'Verify the salary range against industry standards and research the company.', NOW(), NOW()),
('work from home guaranteed', 'Unrealistic Offer', 'Guaranteed remote work with high pay and no qualifications is an unrealistic offer typical of scams.', 'Research the company thoroughly before proceeding.', NOW(), NOW()),
('daily payout', 'Unrealistic Offer', 'Most legitimate jobs pay weekly, biweekly, or monthly. Daily payout promises are a scam tactic.', 'Be very skeptical of daily payment promises. Verify the employer.', NOW(), NOW()),
('passive income', 'Unrealistic Offer', 'Passive income job offers are almost always pyramid schemes or scams requiring upfront investment.', 'Avoid any job that promises passive income without clear legitimate work.', NOW(), NOW()),
('high salary for students', 'Unrealistic Offer', 'Targeting students with unrealistically high salaries is a common scam recruitment tactic.', 'Verify the company and job through official sources before applying.', NOW(), NOW()),
('no interview required', 'Unrealistic Offer', 'Legitimate jobs require interviews. Skipping the interview process is a major red flag.', 'Do not accept any job offer without a proper interview process.', NOW(), NOW()),
('earn while sleeping', 'Unrealistic Offer', 'No legitimate job pays you while you sleep without significant prior investment or work.', 'Avoid these offers entirely. They are almost always scams.', NOW(), NOW()),
('quick money', 'Unrealistic Offer', 'Quick money schemes are designed to lure victims into scams or pyramid schemes.', 'Be very cautious of any job promising quick or easy money.', NOW(), NOW()),
('urgent hiring', 'Urgency', 'Creating artificial urgency pressures applicants into skipping due diligence and making hasty decisions.', 'Take your time to research the company before applying.', NOW(), NOW()),
('apply now limited slots', 'Urgency', 'Fake scarcity is used to pressure applicants into acting without thinking.', 'Do not let urgency rush your decision. Research first.', NOW(), NOW()),
('immediate start', 'Urgency', 'Requiring immediate start without proper onboarding is suspicious and pressures applicants to skip vetting.', 'Always take time to verify the employer before committing.', NOW(), NOW()),
('hiring for today', 'Urgency', 'Same-day hiring without proper interviews or background checks is a major red flag.', 'Never accept a job without proper verification of the employer.', NOW(), NOW()),
('first come first served', 'Urgency', 'This tactic creates false urgency to prevent applicants from doing proper research.', 'Take your time. Legitimate jobs will still be available after you research.', NOW(), NOW()),
('send personal information', 'Data Harvesting', 'Requesting personal information before a formal job offer is a data harvesting scam.', 'Never send personal information before verifying the employer is legitimate.', NOW(), NOW()),
('send government ID', 'Data Harvesting', 'Scammers collect government IDs for identity theft. Only share IDs after verifying the employer.', 'Do not send government IDs to unverified employers.', NOW(), NOW()),
('submit TIN number', 'Data Harvesting', 'Your TIN number can be used for tax fraud. Never share it before formal employment.', 'Only provide your TIN after signing an official employment contract.', NOW(), NOW()),
('provide mother''s maiden name', 'Data Harvesting', 'This is a common security question answer used to steal accounts and commit identity fraud.', 'Never provide this information to a potential employer.', NOW(), NOW()),
('send me your OTP', 'Data Harvesting', 'No legitimate employer ever needs your OTP. This is account takeover fraud.', 'Never share OTPs with anyone, including supposed employers.', NOW(), NOW()),
('copy of bank statement', 'Data Harvesting', 'Requesting bank statements before employment is identity theft preparation.', 'Do not share financial documents with unverified employers.', NOW(), NOW()),
('log into your bank account', 'Data Harvesting', 'No legitimate employer will ever ask you to log into your bank account for them.', 'Refuse immediately and report the recruiter.', NOW(), NOW()),
('optimization tasks', 'Scam Pattern', 'App or search optimization tasks are a common fake job scam where victims eventually lose money.', 'Avoid any job involving optimization tasks with upfront deposits.', NOW(), NOW()),
('click buttons', 'Scam Pattern', 'Click-to-earn schemes are scams that eventually require deposits before allowing withdrawals.', 'Do not participate in click-to-earn job schemes.', NOW(), NOW()),
('watch videos and earn', 'Scam Pattern', 'Watch-and-earn platforms are scams that trap victims into depositing money to unlock fake earnings.', 'Avoid any platform that pays you to watch videos with no legitimate business model.', NOW(), NOW()),
('data entry task', 'Scam Pattern', 'While some data entry jobs are real, many are scams involving fees or personal data collection.', 'Research the company carefully before accepting data entry work.', NOW(), NOW()),
('crypto investment', 'Scam Pattern', 'Crypto investment job scams (pig butchering) lure victims into fake platforms and steal their money.', 'Never invest cryptocurrency based on a job offer. Report it immediately.', NOW(), NOW()),
('buy USDT', 'Scam Pattern', 'Being asked to buy USDT (cryptocurrency) for a job is always a scam.', 'Refuse and report the recruiter immediately.', NOW(), NOW()),
('trading platform', 'Scam Pattern', 'Fake trading platform jobs require victims to deposit funds that are then stolen.', 'Never deposit money into a trading platform recommended by a job recruiter.', NOW(), NOW());